# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">RESMÎ / KURUMSAL E-POSTA VE DİLEKÇENİN YAPI UNSURLARI</text>\n  <rect x="25" y="48" width="320" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Kurumsal E-Posta Anatomisi</text>\n  <text x="40" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Alıcı / CC / BCC:</tspan> Doğru adres ve</text>\n  <text x="48" y="112" font-size="10.5" fill="#1e3a8a">bilgilendirilecek paydaşların seçimi</text>\n  <text x="40" y="132" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Konu (Subject):</tspan> Kısa, açık ve içerikle</text>\n  <text x="48" y="148" font-size="10.5" fill="#1e3a8a">doğrudan uyumlu başlık (boş bırakılmaz!)</text>\n  <text x="40" y="168" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Hitap:</tspan> "Sayın İlgili,", "Değerli Öğretmenim,"</text>\n  <text x="40" y="188" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Gövde:</tspan> Giriş (amaç) + Gelişme + Sonuç (talep)</text>\n  <text x="40" y="208" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Kapanış ve İmza:</tspan> "Saygılarımla," + Ad Soyad</text>\n  <text x="48" y="224" font-size="10.5" font-weight="bold" fill="#1d4ed8">+ Ek (Attachment) kontrolü ve dosya adı</text>\n\n  <rect x="365" y="48" width="310" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Dilekçe Yazım Kuralları</text>\n  <text x="380" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Hitap Makamı:</tspan> Kurum adı (Büyük harf veya</text>\n  <text x="388" y="112" font-size="10.5" fill="#14532d">baş harfleri büyük, satır ortalanmış)</text>\n  <text x="380" y="134" font-size="11" fill="#14532d">• <tspan font-weight="bold">Metin:</tspan> Durum ve talep nesnel, duru bir</text>\n  <text x="388" y="150" font-size="10.5" fill="#14532d">dille açıklanır; "... gereğini arz ederim."</text>\n  <text x="380" y="172" font-size="11" fill="#14532d">• <tspan font-weight="bold">Sağ Alt Köşe:</tspan> Tarih, İmza, Adı ve Soyadı</text>\n  <text x="380" y="194" font-size="11" fill="#14532d">• <tspan font-weight="bold">Sol Alt Köşe:</tspan> Açık Adres, Telefon ve</text>\n  <text x="388" y="210" font-size="10.5" fill="#14532d">varsa EKLER listesi</text>\n  <text x="380" y="228" font-size="10.5" font-weight="bold" fill="#15803d">• Vatandaş makama daima "arz eder"!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAZMA SÜRECİNİ DEĞERLENDİRME ÖLÇÜTLERİ (TDE4.4)</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. İçerik ve Yapı Ölçütleri</text>\n  <text x="32" y="100" font-size="10.5" fill="#334155">• Yazma amacına ve hedef kitleye</text>\n  <text x="40" y="116" font-size="10.5" fill="#475569">(özel/resmî) uygunluk</text>\n  <text x="32" y="138" font-size="10.5" fill="#334155">• Konu başlığı, hitap, gövde ve</text>\n  <text x="40" y="154" font-size="10.5" fill="#475569">imza bölümlerinin tamlığı</text>\n  <text x="32" y="176" font-size="10.5" fill="#334155">• Düşünceler arası mantıksal</text>\n  <text x="40" y="192" font-size="10.5" fill="#475569">tutarlılık (bağdaşıklık)</text>\n  <text x="32" y="214" font-size="10.5" font-weight="bold" fill="#1e40af">• Öznel ve nesnel yargı dengesi</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Dil ve Anlatım İlkeleri</text>\n  <text x="257" y="100" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Açıklık:</tspan> Anlam bulanıklığı olmaması</text>\n  <text x="257" y="124" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Duruluk:</tspan> Gereksiz sözcük bulunmaması</text>\n  <text x="257" y="148" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Yalınlık:</tspan> Yapay süsten uzaklık</text>\n  <text x="257" y="172" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Akıcılık:</tspan> Kolay ve pürüzsüz okunuş</text>\n  <text x="257" y="196" font-size="10.5" fill="#334155">• Yabancı sözcükler yerine Türkçe</text>\n  <text x="265" y="212" font-size="10.5" font-weight="bold" fill="#b45309">karşılıkların tercih edilmesi</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">3. Yazım, Noktalama ve Paylaşım</text>\n  <text x="482" y="100" font-size="10.5" fill="#334155">• Hitap kelimelerinden sonra virgül</text>\n  <text x="490" y="116" font-size="10.5" fill="#475569">ve büyük harf kullanımı</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">• Kurum ve kuruluş adlarına gelen</text>\n  <text x="490" y="154" font-size="10.5" fill="#475569">eklerin kesmeyle ayrılmaması</text>\n  <text x="482" y="176" font-size="10.5" fill="#334155">• Öz ve akran değerlendirmesi</text>\n  <text x="482" y="198" font-size="10.5" font-weight="bold" fill="#6b21a8">• Geri bildirimlerle yeni yazma</text>\n  <text x="490" y="214" font-size="10.5" font-weight="bold" fill="#6b21a8">hedefleri ve yazar kimliği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÖZ DEĞERLENDİRMEDEN ÖZGÜN YAZAR KİMLİĞİNE GEÇİŞ DÖNGÜSÜ</text>\n  <rect x="25" y="55" width="195" height="175" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="122" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Öz Değerlendirme</text>\n  <text x="38" y="106" font-size="10.5" fill="#334155">• Yazarın kendi metnini</text>\n  <text x="38" y="122" font-size="10.5" fill="#334155">içerik, dil, anlatım ve</text>\n  <text x="38" y="138" font-size="10.5" fill="#334155">yazım ölçütlerine göre</text>\n  <text x="38" y="154" font-size="10.5" fill="#334155">kontrol listesiyle</text>\n  <text x="38" y="170" font-size="10.5" fill="#334155">sorgulaması (Öz yansıtma).</text>\n\n  <rect x="252" y="55" width="195" height="175" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Paydaş Geri Bildirimi</text>\n  <text x="265" y="106" font-size="10.5" fill="#334155">• Akran ve öğretmen</text>\n  <text x="265" y="122" font-size="10.5" fill="#334155">görüşleriyle metindeki</text>\n  <text x="265" y="138" font-size="10.5" fill="#334155">eksiklerin, anlam</text>\n  <text x="265" y="154" font-size="10.5" fill="#334155">bulanıklıklarının yapıcı</text>\n  <text x="265" y="170" font-size="10.5" fill="#334155">biçimde belirlenmesi.</text>\n\n  <rect x="480" y="55" width="195" height="175" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="577" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. Yazar Kimliği ve Paylaşım</text>\n  <text x="493" y="106" font-size="10.5" fill="#334155">• Geri bildirimlerle metne</text>\n  <text x="493" y="122" font-size="10.5" fill="#334155">son şeklini verme, yeni</text>\n  <text x="493" y="138" font-size="10.5" fill="#334155">yazma hedefleri belirleme,</text>\n  <text x="493" y="154" font-size="10.5" fill="#334155">özgün üslup kazanma ve</text>\n  <text x="493" y="170" font-size="10.5" font-weight="bold" fill="#15803d">okul ortamlarında paylaşma.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
